    if not self.data_exists:
        raise RecordDoesNotExistError("Data does not exist")

    data_dict = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self.data):
                raise IndexError(f"Index out of bounds: {key}")
            data_dict[self.data[key]] = self.data[key]
        else:
            if key not in self.data:
                data_dict[key] = None
            else:
                data_dict[key] = self.data[key]

    return data_dict

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < len(self):
                result[self._fields[key]] = self._data[key]
            else:
                result[self._fields[key]] = None
                raise IndexError(f"Index {key} out of bounds for record of length {len(self)}")
        elif isinstance(key, str):
            if key in self._fields:
                result[key] = self._data[self._fields[key]]
            else:
                result[key] = None
        else:
            raise TypeError(f"Unsupported type {type(key)} for key")
    return result

def data(self, *keys):
    record_keys = set(self.fields)  # Ensure keys are unique and check against existing fields
    values = {}

    for key in keys:
        if isinstance(key, int) and key in range(len(record_keys)):
            values[record_keys[key]] = self[key]  #正确访问字典 getElement
        elif isinstance(key, str) and key in record_keys:
            values[key] = self[key]  #正确访问字典 getElement
        elif key is None:
            continue  #忽略 None 索引
        else:
            raise IndexError(f"Index {key} out of range for the record keys.")

    return values

