def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")
    if n < 0:
        return -round_half_to_even(-n)

    if n.is_integer():
       return int(n)

    fractional_part = n - int(n)
    if fractional_part >= 0.5:
        return int(n) + 1
    elif fractional_part > 0.25 and fractional_part < 0.5:
        return int(n)
    elif fractional_part > 0.25:
        return int(n) + 1
    else:
        return int(n)

def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be an integer or float.")

    if n == float('inf') or n == float('-inf'):
        raise ValueError("Cannot round infinity.")

    if n == 0:
        return 0

    if n % 1 == 0:
        return int(n)

    fractional_part = n % 1
    rounded_part = int(n) if fractional_part < 0.5 else int(n) + 1

    return rounded_part

def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number.")

    if math.isnan(n):
        raise ValueError("Input cannot be NaN.")

    if abs(n) == math.inf:
        raise ValueError("Input cannot be infinity.")

    if not (n == int(n) or (n % 1 == 0.5 and n > 0 and abs(n - int(n)) > abs(int(n) - 1)) or (n == -int(n) or (n % 1 == -0.5 and n < 0 and abs(n - int(n)) > abs(int(n) + 1))):
        raise ValueError("Input is not a valid number.")

    if n > 0:
        return int(math.ceil(n - 0.5))
    else:
        return int(math.floor(n + 0.5))

def round_half_to_even(n):
    if not isinstance(n, (int, float)) or not isfinite(n):
        raise ValueError("Input must be a finite number")
    if n % 2 == 0:
        return round(n)
    else:
        return int(floor(n + 0.5)) if n - floor(n) < 0.5 else int(ceil(n - 0.5))

