def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """

    class Point(type(subclass)):
        def __init__(self, name, fields, srid_map):
            super().__init__(name, fields, srid_map)

    return Point(name, fields, srid_map)

def point_type(name, fields, srid_map):
    import string
    import sys
    if not isinstance(name, str):
        raise ValueError("name must be a string")
    if not isinstance(fields, list):
        raise ValueError("fields must be a list")
    if not isinstance(srid_map, dict):
        raise ValueError("srid_map must be a dictionary")

    base_name = name.capitalize()
    fields_with_red = [name] + fields

    class_definition = f"class {base_name}(BaseGeometry):"
    for field in fields_with_red:
        field_type = srid_map.get(field, 'float')
        field_data_type = field_type if field_type != 'float' else 'str'
        if field_type == 'float':
            class_definition += f"\n    {field} = Point"
        else:
            class_definition += f"\n    {field} = {field_data_type}"

    return class_definition

def point_type(name, fields, srid_map):
    try:
        # Dynamically generate the class source code
        class_source = f"class {name}(lat, lon):\n"
        for field in fields:
            class_source += f"    def {field}(self, value):\n"
            class_source += "        self.{field} = value\n".format(field=field)
        importlib.util.module_from_source(bytearray(class_source.encode('utf-8')), name)
        return True
    except Exception as e:
        print(f"Error creating point type: {e}")
        return False

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    from point import(Point)

    class DynamicPoint(Point):
        def __init__(self, *args, **kwargs):
            if len(args) != 2:
                raise ValueError("Args should be two 3D points")
            for field in fields:
                if field not in kwargs:
                    raise ValueError(f"Field '{field}' is missing in the keyword arguments")
                if numpy.isnan(kwargs[field]):
                    raise ValueError(f"Field '{field}' is nan")
                setattr(self, field, kwargs[field])
            super().__init__(*args)

    point_type_map[name] = DynamicPoint

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.

    Parameters:
        name (str): Name of the Point subclass.
        fields (list): List of fields for the Point subclass.
        srid_map (dict): Mapping of SRID codes to coordinate systems.

    Returns:
        type: Dynamically created Point subclass.
    """
    if not isinstance(name, str) or not isinstance(fields, list) or not isinstance(srid_map, dict):
        raise ValueError("Invalid input types. Expecting str, list, and dict.")

    class Point(subclass(Base Model)):
        class Meta:
            verbose_name = name
            verbose_name_plural = f"{name.capitalize()}s"

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.set_x_field(fields)
            self.set_y_field(fields)

        def set_x_field(self, fields):
            x_field = fields.get('x')
            if not x_field:
                raise ValueError("Missing 'x' field in field list.")
            setattr(self, x_field, Depends(lambda: x_field))

        def set_y_field(self, fields):
            y_field = fields.get('y')
            if not y_field:
                raise ValueError("Missing 'y' field in field list.")
            setattr(self, y_field, Depends(lambda: y_field))

        def description(self):
            return f"Point object with coordinates X={self.x} and Y={self.y}"

    return Point

