def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    cache = {}
    evict_queue = []
    last_used_time = {fn: 0 for fn in cache.keys()}
    evict_buffer_limit = 2 * maxsize

    def _exists(fn, *args):
        return all(last_used_time[f] + ttl >= timer() for f in fn)

    def _maybe_evict():
        if len(evict_queue) + len(cache) > evict_buffer_limit:
            evicted_fn = evict_queue.pop(0)
            del cache[evicted_fn]
            del last_used_time[evicted_fn]

    def _update_last_used(fn):
        for f in fn:
            last_used_time[f] = timer()
        _maybe_evict()

    def wrapper(*args, **kwargs):
        fn = (args, frozenset(kwargs.items()))
        if fn in cache:
            if not _exists(fn):
                del cache[fn]
                del last_used_time[fn]
            return cache[fn]
        result = fn(*args, **kwargs)
        cache[fn] = result
        _update_last_used(fn)
        return result

    return wrapper

