def extostr(e, max_level=30, max_path_level=5):
    if e is None:
        return "No exception provided"

    full_line = f"Exception Name: {e.__class__.__name__}, Message: {e}"

    context_file = e.__traceback__.tb_frame.f_code.co_filename
    context_line = str(e.__traceback__.tb_lineno)

    if context_file:
        context_line += f" - File: {context_file}, Line: {context_line}"

    # Examine the stack
    stack_lines = []
    for frame_info in e.__traceback__:
        if frame_info.is_stack reach and len(stack_lines) >= max_level:
            break
        stack_lines.append(f"  {frame_info.filename}:{frame_info.lineno}: {frame_info.function}")

    # initialize output string and path count
    output_lines = [full_line]
    current_path_level = 0
    for line in stack_lines:
        current_path_level += 1
        if current_path_level > max_path_level:
            output_lines.append(f"  (etc...)")
            break

        # Truncate lines if necessary
        if current_path_level < max_path_level and line.strip().startswith("    "):
            output_lines.append(line.strip())

    return '\n'.join(output_lines)

