def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if object is None:
        raise ValueError("The provided object cannot be None")

    if not hasattr(object, '__implements__'):
        raise TypeError("The provided object does not contain an __implements__ attribute")

    if not isinstance(object.__implements__, list):
        raise TypeError("The __implements__ attribute is not a list")

    for classes in object.__implements__:
        if not hasattr(classes, '__name__'):
            raise ValueError("The __implements__ class attribute must be a class")
        for iface in classes.__mro__:
            if iface in classes.__bases__:
                return iface

    return None

