            raise ValueError("Fixity block must contain key-value pairs where keys are strings and values are strings or lists")

        # Ensure that only files listed in the manifest are referenced
        referenced_files = set()
        for item in fixity.values():
            if isinstance(item, str):
                referenced_files.add(item)
            elif isinstance(item, list):
                referenced_files.update(item)

        if referenced_files != set(manifest_files):
            raise ValueError("Not all referenced files are in the manifest")

