def add_rendition(self, lang, file_path):
    if not lang or not file_path:
        raise ValueError("Both language and file path are required.")

    # Assuming the response from the enigma-machine is stored in the 'response' variable
    if lang == "en" and file_path.endswith(".pdf"):
        return {"original": file_path, lang: f"{file_path.split('.')[0]}-{lang}.pdf"}
    elif lang != "en" and file_path.endswith(".pdf"):
        response = self.enigma_machine.process_text(file_path)
        if response:
            return {"original": file_path, lang: response + "-" + lang + ".pdf"}
        else:
