def _extract_number_and_supplement_from_issue_element(issue):
    if not issue:
        raise ValueError("The issue element is empty.")

    def parse_support_spec(text):
        parts = text.split(" ")
        number = 0
        suppl = 0
        for part in parts:
            if part.isdigit():
                number = int(part)
            else:
                suppl += int(part)
        if "pr" in text:
            suppl += 1
        return number, suppl

