    numbers = []
    supplements = []

    for content in issue_content:
        parts = content.split(". ")
        if len(parts) >= 2:
            number, suppl = parse_support_spec(parts[-1])
            numbers.append(number)
            supplements.append(suppl)

    return numbers, supplements

def _extract_number_and_suppl_from_issue_element(issue):
    # Define patterns for the number and supplement
    number_pattern = re.compile(r'(\d+)')
    supplement_pattern = re.compile(r'([a-zA-Z\s]+)(\s+)(\d+)_chunk')

    # Search for the number pattern in the issue content
    match = number_pattern.search(issue)
    if match:
        number = match.group(1)
    else:
        number = None

    # Search for the supplement pattern in the issue content
    match = supplement_pattern.search(issue)
    if match:
        supplement = match.group(2)
        supplement_chunk = match.group(3)
        if supplement_chunk == '_chunk':
            supplement_chunk = 1
        else:
            supplement_chunk = int(supplement_chunk)
    else:
        supplement = None
        supplement_chunk = None

    return number, supplement, supplement_chunk

