def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
            hook.

    """
    if not isinstance(hook, HookType):
        raise ValueError("hook must be an instance of HookType")

    def decorator(listener):
        if not callable(listener):
            raise ValueError("listener must be a callable function")

        if hook not in self.registry:
            self.registry[hook] = []

        self.registry[hook].append(listener)

        def wrapper(*args, **kwargs):
            for listener in self.registry[hook]:
                listener(*args, **kwargs)
        return wrapper

    return decorator

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
            hook.

    """

    def inner_decorator(func):
        # Handle edge cases and existing handlers for the given hook
        if hook in self.registry:
            existing_handler = self.registry[hook]
            if callable(existing_handler):
                raise TypeError(f"Hook {hook} is already defined. You should merge existing handlers.")
            self.registry[hook] = {'function': existing_handler, 'parameters': []}
        else:
            self.registry[hook] = {'function': func, 'parameters': []}

        # Return a callable that wraps the decorated function for initialization
        def wrapper(*args, **kwargs):
            # Add parameters to the function call and update the registry
            if hook not in self.parameters:
                self.parameters[hook] = []
            self.parameters[hook].append((args, kwargs))
            return func(*args, **kwargs)

        return wrapper

    return inner_decorator

