    if len(content_differences) > 0:
        self.logger.error(f"Content differences found in the last version: {content_differences}")
        return False

    return True

def validate_version_inventories(self, version_dirs):
    inventory_map = {}
    digests_to_check = set()

    for dir_name in version_dirs:
        try:
            listing = os.listdir(os.path.join(f'storage/inventories', dir_name))
            for item in listing:
                item_path = os.path.join(f'storage/inventories', dir_name, item)
                if os.path.isdir(item_path):
                    version_dir = os.path.basename(item_path)
                    sub_inventory = os.listdir(item_path)
                    inventory_map[version_dir] = sub_inventory
                    if item.endswith('~'):
                        digests_to_check.add(item[:-1])
                    else:
                        digests_to_check.add(item)

            if dir_name != 'root':
                if 'root' in inventory_map:
                    root_inventory_sub_dirs = set(sub_inventory) - set(inventory_map['root'])
                    digests_to_check.update(root_inventory_sub_dirs)

        except FileNotFoundError:
            logging.error(f'Folder {dir_name} not found')
            continue
        except Exception as e:
            logging.error(f'Error processing folder {dir_name}: {e}')

    return inventory_map, digests_to_check

