                continue

            inventory_data = open(inventory_path, 'r').read()
            # Add logic to parse inventory data and check for content digests
            distinct_content_hashes.add(inventory_data)
            version_to_inventory[version_dir] = inventory_data

    # Check if the inventory data matches the root inventory
    root_inventory_data = open(root_inventory, 'r').read()
    if root_inventory_data not in version_to_inventory.values():
