            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        raise ValueError("Size cannot be empty")

    size = size.upper()
    units = ('K', 'M', 'G', 'T')
    multiplier = 1

    for unit in units:
        if size.endswith(unit):
            if unit == 'K':
                multiplier = 1024
            elif unit == 'M':
                multiplier = 1024 * 1024
            elif unit == 'G':
                multiplier = 1024 * 1024 * 1024
            elif unit == 'T':
                multiplier = 1024 * 1024 * 1024 * 1024
            break

    if multiplier == 1:
        return int(size)
    else:
        return int(size[:-1]) * multiplier

