def split(s, platform=''):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not s:
        return []

    if platform == 'this':
        platform = 'posix' if 'win' not in sys.platform else 'cmd'
    elif platform not in ('posix', 'cmd'):
        raise ValueError("Invalid platform value. Expected 'posix' or 'cmd'.")

    # Use the appropriate regex to split the input string
    if platform == 'posix':
        return re.split(r' ?[;+\s]\s*', s)
    else:
        return re.split(r' ?[;+]?\s*', s)

def split(s, platform='this'):
    if platform == 'this':
        return re.split(r'[^\w\'''",\s]', s)
    elif platform == 1:
        return re.split(r'[\W\''",\s]', s)
    elif platform == 0:
        return re.split(r'[\W\''",\s]', s)
    else:
        raise ValueError("Unsupported platform")

