def add_ignored(ignored):
    new_ignored = []
    try:
        # Obtain the list of ignored files using git ls-files command
        git_ls_files_output = subprocess.check_output(['git', 'ls-files', '--ignored'], text=True)
        # Convert the output to a list of file names
        file_names = git_ls_files_output.splitlines()
        # Ensure the list contains all ignored files
        for file_name in ignored:
            if file_name in file_names:
                new_ignored.append(file_name)
    except subprocess.CalledProcessError as e:
        # Handle the case where git ls-files command fails
        print(f"Error: {e}")
        return ""
    # Return the list of ignored files separated by commas
    return ", ".join(new_ignored)

