def subprocess_run_helper(func, *args, timeout, extra_env=None):
    # Attempt to import the module containing the function
    try:
        module_name = func.__name__.replace('.', '__')
        module = __import__("{}.{}".format(__name__, module_name), fromlist=[''])
    except ModuleNotFoundError:
        raise ImportError(f"Module '{func.__name__}' not found")

    # Construct the subprocess command
    command = ['python', module.__file__, *[arg for arg in args if arg is not None], f'timeout={timeout}']
    if extra_env:
        command.extend(['env', ' '.join(f"{key}={value}" for key, value in extra_env.items())])

    try:
        # Run the subprocess with timeout
        subprocess.run(command, check=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise TimeoutError(f"Process runtime exceeded {timeout} seconds")
    except Exception as e:
        raise subprocess.CalledProcessError(f"Command failed with exit code {e.returncode}")

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    try:
        if extra_env:
            # Use subprocess.run's env keyword to set environment variables
            result = subprocess.run([func] + list(args), timeout=timeout, env=extra_env)
        else:
            # Use subprocess.run's args keyword to pass arguments and no environment variables
            result = subprocess.run([func] + list(args), timeout=timeout)
    except subprocess.CalledProcessError as e:
        # Handle runtime issues by raising a new exception with the same message
        raise subprocess.CalledProcessError(f"Failed to execute function '{func}' with arguments {args}: {e}")
    except TimeoutExpired:
        # Handle timeout issues by raising a new exception
        raise TimeoutExpired(f"Function '{func}' timed out after {timeout} seconds")
    else:
        return result

