def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    roots = set() if roots is None else roots

    # Create a dictionary to hold all nodes encountered during traversal
    node_dict = {}

    # Function to perform a DFS traversal
    def dfs(node):
        nonlocal roots, node_dict
        if node in node_dict:
            return
        node_dict[node] = True
        for parent in graph.predicates(node):
            if parent == prop:
                child = next(graph.objects(node))
                if child not in node_dict:
                    dfs(child)

    # Start DFS traversal from all nodes
    for node in graph:
        if node not in node_dict:
            dfs(node)

    # Return the set of roots
    return roots

