def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not hist:
        raise ValueError("Histogram cannot be empty")

    if scale is None:
        scale = True  # Use the histogram scale if scale is None

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid coordinate type")

    if len(field_names) != len(hist):
        raise ValueError("Field names must match the dimension of the histogram")

    graph = []
    for bin_ in hist:
        if make_value is not None:
            value = make_value(bin_)
        else:
            value = bin_

        x_value = bin_[0]
        if get_coordinate == "left":
            x = x_value
        elif get_coordinate == "right":
            x = x_value + bin_[1]
        else:
            x = 0.5 * (x_value + x_value + bin_[1])

        graph.append((x, value))

    if scale:
        graph.sort(key=lambda item: item[0])

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not (isinstance(hist, list) and all(isinstance(bin_, tuple) for bin_ in hist)):
        raise ValueError("hist must contain only numeric bins")

    def make_value_numeric(bin_):
        if make_value is None:
            return bin_[0]
        return make_value(bin_)[0]

    # Initialize graph with placeholders
    graph = {}

    bin_edges = sorted(set(bin_[1] for bin_ in hist))
    for i, x in enumerate(bin_edges):
        if i == 0:
            left_edge = None
        else:
            left_edge = bin_edges[i-1]

        if i == len(bin_edges) - 1:
            right_edge = None
        else:
            right_edge = bin_edges[i+1]

        if get_coordinate == "left":
            x_coordinate = x
        elif get_coordinate == "right":
            x_coordinate = right_edge
        elif get_coordinate == "middle":
            x_coordinate = (left_edge + right_edge) / 2
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        binary_values = [(make_value_numeric(bin_), bin_[1]) for bin_ in hist if bin_[1] >= left_edge and bin_[1] < right_edge]

        if not binary_values:
            continue

        y_values = [value for value, edge in binary_values]
        y_mean = sum(y_values) / len(y_values)
        y_min = min(y_values)
        y_max = max(y_values)

        if scale is None:
            scale = 1  # Default scale is 1 (equal bin sizes)

        # Assuming 2D for simplicity, might need to adjust if 1D is desired
        graph[x_coordinate] = (y_mean, y_min, y_max)

    return graph

def hist_to_graph(hist: List[Bin], make_value: Callable[[Bin], float] = None, 
                  get_coordinate: str = "left", field_names: Tuple[str, ...] = ("x", "y"), 
                  scale: Any = None) -> Graph:
    # Validate input
    if not all(isinstance(bin_, Bin) for bin_ in hist):
        raise ValueError("hist must contain only numeric bins")

    # Apply make_value if provided
    if make_value:
        for bin_ in hist:
            bin_.content = make_value(bin_)

    # Determine graph points
    points = []
    for bin_ in hist:
        if get_coordinate == "left":
            point = (bin_.content, bin_.content, bin_.content)
        elif get_coordinate == "right":
            point = (bin_.content, bin_.content + bin_.content, bin_.content + bin_.content)
        elif get_coordinate == "middle":
            point = (bin_.content, bin_.content + bin_.content / 2, bin_.content + bin_.content / 2)
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        points.append(point)

    # Scale the graph if necessary
    if scale is True:
        scale_value = min(bin_.content for bin_ in hist)
        for point in points:
            point = (point[0] * scale_value, point[1] * scale_value, point[2] * scale_value)

    # Create and return the graph
    return Graph(points)

