def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Process extra_vars
    if extra_vars is None:
        extra_vars = {}
    else:
        extra_vars = {''.join([k, '=', repr(v)]): v for k, v in extra_vars.items()}

    # Process ansible_args
    if ansible_args is None:
        ansible_args = {}
    else:
        args_desc = ' '.join([f"{key}={value}" for key, value in ansible_args.items()])
        args_desc += f" --extra-vars '{extra_vars}'"
    else:
        args_desc = f" --extra-vars '{extra_vars}' {args_desc}"

    # Construct the command
    cmd = [ir_plugin.ansible_binary, '-f', str(ir_workspace.frags_facts_count), playbook_path] + args_desc.split()

    # Execute the command
    try:
        output = subprocess.check_output(cmd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
        return output
    except subprocess.CalledProcessError as e:
        error_message = e.stderr.strip()
        raise Exception(f"Failed to execute ansible-playbook. Error: {error_message}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {str(e)}")

